package castbridge.core.lots

import castbridge.core.tv.ApiExtension
import castbridge.core.tv.ApiReply
import castbridge.core.tv.ReceiverServer

/**
 * Pure decisions about the installation key's envelope (the Android code only maps its exceptions onto these inputs). Rule of the lifecycle (audits w4-03): an existing `install.key` is NEVER
 * overwritten, moved or regenerated by itself; only an explicit owner reset replaces it (and keeps the old files). A key that cannot be read for now is retried (backoff), never given up.
 */
object InstallKeyPolicy {
    /** Why an unwrap failed, as the Android code sees it. */
    enum class UnwrapFailure { BAD_TAG, MISSING_ALIAS, INVALIDATED, OTHER }
    enum class Verdict { LOST, TRANSIENT }

    /**
     * LOST (the wrapper answers null: unreadable until an owner reset) only for a wrong tag, a permanently invalidated key, or an alias confirmed absent ([aliasConfirmedAbsent]); anything
     * else (Keystore daemon restarting, locked, any other exception) is TRANSIENT: the wrapper throws, the file stays as it is and the caller retries later.
     */
    fun classify(f: UnwrapFailure, aliasConfirmedAbsent: Boolean = false): Verdict = when (f) {
        UnwrapFailure.BAD_TAG, UnwrapFailure.INVALIDATED -> Verdict.LOST
        UnwrapFailure.MISSING_ALIAS -> if (aliasConfirmedAbsent) Verdict.LOST else Verdict.TRANSIENT
        UnwrapFailure.OTHER -> Verdict.TRANSIENT
    }

    /** A missing alias is believed only when `containsAlias` said false, then a freshly reloaded KeyStore says false again AND returns no key (null = the lookup threw: not confirmed). */
    fun aliasConfirmedAbsent(containsFirst: Boolean?, containsReloaded: Boolean?, keyReloaded: Boolean?): Boolean = containsFirst == false && containsReloaded == false && keyReloaded == false

    /** Pause between the two checks of the missing-alias double confirmation (a Keystore daemon restarting answers « absent » for a moment). */
    const val CONFIRM_PAUSE_MS = 1_500L

    /**
     * The double confirmation with its pause: false at once if [containsFirst]; otherwise waits [CONFIRM_PAUSE_MS] through [sleeper] (injectable: tests do not sleep), then
     * [reload] (a freshly reloaded KeyStore: containsAlias, key returned) decides through [aliasConfirmedAbsent]. An exception of [reload] is not a confirmation: it propagates.
     */
    fun confirmAbsent(containsFirst: Boolean, sleeper: (Long) -> Unit = { Thread.sleep(it) }, reload: () -> Pair<Boolean?, Boolean?>): Boolean {
        if (containsFirst) return false
        sleeper(CONFIRM_PAUSE_MS)
        val (contains, key) = reload()
        return aliasConfirmedAbsent(false, contains, key)
    }

    /**
     * May the owner reset be accepted? Only when the key is really unreadable ([KeyState.UNREADABLE]), or still PENDING with NO key file (nothing to lose). Never in `keystore` (it works),
     * never in `unavailable` (the key may well be recoverable: a reset could replace the real Keystore alias) and never in `pending` while a key file exists.
     */
    fun resetAllowed(state: KeyState, fileExists: Boolean): Boolean = when (state) {
        KeyState.UNREADABLE -> true
        KeyState.PENDING -> !fileExists
        KeyState.READY, KeyState.UNAVAILABLE -> false
    }

    /** The state of the key as the admin page shows it (`installKeyProtection`). */
    enum class KeyState(val protection: String) { PENDING("pending"), READY("keystore"), UNAVAILABLE("unavailable"), UNREADABLE("unreadable") }

    // ---- the retry schedule when the key cannot be read or created for now (Keystore unavailable): time-based only ----
    const val SHORT_DELAY_MS = 60_000L                  // 1 min between the first attempts …
    const val LONG_DELAY_MS = 3_600_000L                // … then 1 h
    const val SHORT_TRIES = 3

    /** The wait before the next attempt after [failures] failures in this process (0 = none yet: try now). */
    fun delayAfter(failures: Int): Long = when { failures <= 0 -> 0L; failures <= SHORT_TRIES -> SHORT_DELAY_MS; else -> LONG_DELAY_MS }

    /** May a new attempt start at [nowMs] (monotonic clock)? [lastFailureAtMs] = time of the last failure in this process, null if none. */
    fun mayAttempt(nowMs: Long, lastFailureAtMs: Long?, failures: Int): Boolean =
        lastFailureAtMs == null || nowMs - lastFailureAtMs >= delayAfter(failures) || nowMs < lastFailureAtMs   // a clock that went back never blocks forever

    /** The French answer of a route that needs the installation key while it cannot be read (HTTP 503). */
    const val UNAVAILABLE_MESSAGE = "coffre de clés indisponible : nouvel essai automatique, réessayez plus tard"
    const val UNREADABLE_MESSAGE = "clé d'installation illisible : réinitialisez-la depuis l'administration (les locations devront être réémises)"
    const val RESET_REFUSED = "réinitialisation refusée : la clé n'est pas illisible"
    const val RESET_FAILED = "réinitialisation impossible : erreur interne, la clé d'installation et ses anciens fichiers sont conservés"
    const val RESET_NOTE = "clé d'installation réinitialisée : réémettez les locations"
}

/** The retry gate: when may the next attempt start (backoff on a monotonic clock, one log line per process). Thread-safe, keeps no file. */
class InstallKeyGate(private val mono: () -> Long) {
    private var lastFailureAt: Long? = null
    @Volatile var failures = 0; private set

    @Synchronized fun mayAttempt(): Boolean = InstallKeyPolicy.mayAttempt(mono(), lastFailureAt, failures)

    /** Records a failure; true for the first one of this process (log it, once). */
    @Synchronized fun failed(): Boolean { val first = failures == 0; failures++; lastFailureAt = mono(); return first }

    @Synchronized fun succeeded() { failures = 0; lastFailureAt = null }
}

/**
 * Routes built LAZILY: [build] runs at the first request of one of [paths], never when the server is set up, and its failure answers 503 « coffre de clés indisponible » instead of reaching
 * the caller (audit w4-03: a failure in `TvService.onCreate` brought the whole TV app down). Other paths are left to the next extension, [bodyPaths] are announced without building anything.
 */
class LazyKeyedApi(private val paths: Set<String>, private val bodyPaths: Set<String>, private val build: () -> ApiExtension) : ApiExtension {
    private fun unavailable() = ApiReply(503, """{"error":${ReceiverServer.q(InstallKeyPolicy.UNAVAILABLE_MESSAGE)}}""")
    private inline fun guarded(path: String, call: (ApiExtension) -> ApiReply?): ApiReply? {
        if (path !in paths) return null
        val api = runCatching(build).getOrElse { return unavailable() }
        return call(api)
    }
    override fun wantsBody(path: String) = path in bodyPaths
    override fun handle(path: String, method: String, params: Map<String, String>) = guarded(path) { it.handle(path, method, params) }
    override fun handleBody(path: String, method: String, params: Map<String, String>, body: ByteArray) = guarded(path) { it.handleBody(path, method, params, body) }
}
